// Follow-up gate for the WhatsApp / SMS support assistant.
// State is in memory only: a restart forgets every user.

const WINDOW_MS = 24 * 60 * 60 * 1000; // WhatsApp customer service window

// Carrier-style keywords, matched as the whole message.
const STOP_WORDS = new Set([
  "STOP", "STOPALL", "UNSUBSCRIBE", "CANCEL", "END", "QUIT", "REVOKE",
  "OPT OUT", "OPT-OUT", "OPTOUT",
]);
const START_WORDS = new Set(["START", "UNSTOP"]);

// userId -> { lastInboundAt: number | null, lastOptEvent: { kind, at } | null }
const users = new Map();

function keywordOf(text) {
  const cleaned = text
    .normalize("NFKC")
    .replace(/\p{Cf}/gu, "") // zero-width and other invisible characters
    .replace(/\s+/g, " ")
    .replace(/^[\p{P}\p{S}\s]+|[\p{P}\p{S}\s]+$/gu, "") // outer punctuation, symbols, spaces
    .toUpperCase();
  if (STOP_WORDS.has(cleaned)) return "stop";
  if (START_WORDS.has(cleaned)) return "start";
  return null;
}

function recordFor(userId) {
  if (typeof userId !== "string" || userId === "") {
    throw new TypeError("userId must be a non-empty string");
  }
  let user = users.get(userId);
  if (!user) {
    user = { lastInboundAt: null, lastOptEvent: null };
    users.set(userId, user);
  }
  return user;
}

export function onInbound(userId, text, at) {
  const user = recordFor(userId);
  if (!(at instanceof Date) || Number.isNaN(at.getTime())) {
    throw new TypeError("at must be a valid Date");
  }
  const t = at.getTime();
  user.lastInboundAt = user.lastInboundAt === null ? t : Math.max(user.lastInboundAt, t);

  // Media messages arrive without a body; they still count as contact.
  const kind = keywordOf(typeof text === "string" ? text : "");
  if (kind) {
    const prev = user.lastOptEvent;
    // The latest opt event wins; on a tie, STOP wins.
    if (!prev || t > prev.at || (t === prev.at && kind === "stop")) {
      user.lastOptEvent = { kind, at: t };
    }
  }
}

function allow() {
  return { allowed: true, rule: null };
}

function block(rule) {
  return { allowed: false, rule };
}

export function check(userId, type, now) {
  if (typeof userId !== "string" || userId === "") return block("invalid-user");
  if (type !== "freeform" && type !== "template") return block("invalid-type");
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return block("invalid-time");

  const user = users.get(userId);
  if (user?.lastOptEvent?.kind === "stop") return block("opted-out");

  const last = user?.lastInboundAt ?? null;
  if (type === "freeform") {
    // Free text only inside 24 h of the customer's last message.
    if (last === null) return block("outside-24h-window");
    const age = now.getTime() - last;
    if (age < 0 || age >= WINDOW_MS) return block("outside-24h-window");
    return allow();
  }

  // Templates need some sign that the customer wrote to us first.
  if (last === null) return block("no-customer-contact");
  return allow();
}

input.command:
node -v && node --input-type=module -e '
const { onInbound, check } = await import("./bot.mjs");
const H = 3600e3, D = new Date("2026-10-23T10:00:00Z");
const at = (ms) => new Date(D.getTime() + ms);
const out = [];
const ok = (name, got, want) => out.push([got === want ? "PASS" : "FAIL", name, JSON.stringify(got)]);
const r = (x) => (x.allowed ? "allow" : "block:" + x.rule);

// never-contacted user
ok("new freeform", r(check("new", "freeform", D)), "block:outside-24h-window");
ok("new template", r(check("new", "template", D)), "block:no-customer-contact");
ok("bad type", r(check("new", "bogus", D)), "block:invalid-type");
ok("bad now", r(check("new", "freeform", new Date("x"))), "block:invalid-time");
ok("bad user", r(check("", "template", D)), "block:invalid-user");

// contact then window
onInbound("a", "hi there", at(0));
ok("freeform in window", r(check("a", "freeform", at(23 * H))), "allow");
ok("freeform at 24h", r(check("a", "freeform", at(24 * H))), "block:outside-24h-window");
ok("template after window", r(check("a", "template", at(48 * H))), "allow");

// keyword variants
for (const s of ["STOP", "stop", " Stop! ", "S-T-O-P-x", "opt out", "Opt-Out", "OPTOUT", "unsubscribe.", "stopall", "END", "quit", "cancel"]) {
  onInbound("k", s, at(1000));
  const want = s === "S-T-O-P-x" ? "allow" : "block:opted-out";
  ok("kw " + JSON.stringify(s), r(check("k", "template", at(2000))), want);
  onInbound("k", "START", at(1500)); // reset for next loop
}
// sentences that only contain the word
for (const s of ["I am stopping by the store", "please don't stop texting me yet", "can you cancel my order?"]) {
  onInbound("s", s, at(0));
  ok("sentence " + JSON.stringify(s), r(check("s", "template", at(1))), "allow");
}

// opt-out blocks freeform and template, restart via START
onInbound("o", "STOP", at(0));
ok("stopped freeform", r(check("o", "freeform", at(1))), "block:opted-out");
ok("stopped template", r(check("o", "template", at(1))), "block:opted-out");
onInbound("o", "UNSTOP", at(10 * H));
ok("restarted template", r(check("o", "template", at(11 * H))), "allow");

// out-of-order: an old START must not undo a newer STOP
onInbound("p", "STOP", at(5 * H));
onInbound("p", "START", at(1 * H));
ok("stale START ignored", r(check("p", "template", at(6 * H))), "block:opted-out");

// media message without body still counts as contact
onInbound("m", undefined, at(0));
ok("media contact", r(check("m", "template", at(1))), "allow");

console.log(out.map((x) => x.join("  ")).join("\n"));
console.log(out.every((x) => x[0] === "PASS") ? "ALL PASS" : "FAILURES");
'

node -v && node --input-type=module <<'EOF'
const { onInbound, check } = await import("./bot.mjs");
const H = 3600e3, D = new Date("2026-10-23T10:00:00Z");
const at = (ms) => new Date(D.getTime() + ms);
const out = [];
const ok = (name, got, want) => out.push([got === want ? "PASS" : "FAIL", name, JSON.stringify(got)]);
const r = (x) => (x.allowed ? "allow" : "block:" + x.rule);

// never-contacted user
ok("new freeform", r(check("new", "freeform", D)), "block:outside-24h-window");
ok("new template", r(check("new", "template", D)), "block:no-customer-contact");
ok("bad type", r(check("new", "bogus", D)), "block:invalid-type");
ok("bad now", r(check("new", "freeform", new Date("x"))), "block:invalid-time");
ok("bad user", r(check("", "template", D)), "block:invalid-user");

// contact then window
onInbound("a", "hi there", at(0));
ok("freeform in window", r(check("a", "freeform", at(23 * H))), "allow");
ok("freeform at 24h", r(check("a", "freeform", at(24 * H))), "block:outside-24h-window");
ok("template after window", r(check("a", "template", at(48 * H))), "allow");

// keyword variants (each on a fresh user so earlier STOPs do not leak)
const stopCases = ["STOP", "stop", " Stop! ", "opt out", "Opt-Out", "OPTOUT", "unsubscribe.", "stopall", "END", "quit", "cancel"];
stopCases.forEach((s, i) => {
  const id = "k" + i;
  onInbound(id, s, at(1000));
  ok("kw " + JSON.stringify(s), r(check(id, "template", at(2000))), "block:opted-out");
});
onInbound("kx", "S-T-O-P-x", at(1000));
ok("not keyword S-T-O-P-x", r(check("kx", "template", at(2000))), "allow");

// sentences that only contain the word
for (const s of ["I am stopping by the store", "please dont stop texting me yet", "can you cancel my order?"]) {
  const id = "s" + s.length;
  onInbound(id, s, at(0));
  ok("sentence " + JSON.stringify(s), r(check(id, "template", at(1))), "allow");
}

// opt-out blocks freeform and template; restart via UNSTOP
onInbound("o", "STOP", at(0));
ok("stopped freeform", r(check("o", "freeform", at(1))), "block:opted-out");
ok("stopped template", r(check("o", "template", at(1))), "block:opted-out");
onInbound("o", "UNSTOP", at(10 * H));
ok("restarted template", r(check("o", "template", at(11 * H))), "allow");

// out-of-order: an older START must not undo a newer STOP
onInbound("p", "STOP", at(5 * H));
onInbound("p", "START", at(1 * H));
ok("stale START ignored", r(check("p", "template", at(6 * H))), "block:opted-out");

// media message without body still counts as contact
onInbound("m", undefined, at(0));
ok("media contact", r(check("m", "template", at(1))), "allow");

console.log(out.map((x) => x.join("  ")).join("\n"));
console.log(out.every((x) => x[0] === "PASS") ? "ALL PASS" : "FAILURES");
EOF
